<?php declare(strict_types=1); namespace App\Modules\Tourism\Models; use App\Core\Database; final class TourismReview{private Database $db;public function __construct(){$this->db=app()->get("db");}public function all(int $t):array{return $this->db->fetchAll("SELECT r.*,u.name user_name FROM tourism_reviews r LEFT JOIN users u ON u.id=r.user_id WHERE r.tenant_id=? ORDER BY r.id DESC",[$t]);}public function status(int $t,int $id,string $s):void{$this->db->execute("UPDATE tourism_reviews SET status=? WHERE tenant_id=? AND id=?",[$s,$t,$id]);}}
